  "history.durable.warning": { ru: "Операция может выполняться долго и продолжится после закрытия страницы или браузера. Она обращается к GPS-провайдеру и может записывать GPS-наблюдения и чекпоинты истории.", uk: "Операція може виконуватися довго й триватиме після закриття сторінки або браузера. Вона звертається до GPS-провайдера та може записувати GPS-спостереження й checkpoint історії.", en: "This operation may run for a long time and continues after the page or browser is closed. It contacts the GPS provider and may write GPS observations and history checkpoints." },
  "history.durable.creating": { ru: "Создание…", uk: "Створення…", en: "Creating…" },
  "history.durable.already": { ru: "Фоновое дозаполнение уже запущено.", uk: "Фонове дозаповнення вже запущено.", en: "Background population is already running." },
  "history.durable.failed": { ru: "Не удалось подтвердить создание запуска. Проверен текущий активный статус; автоматическая повторная отправка не выполнялась.", uk: "Не вдалося підтвердити створення запуску. Перевірено поточний активний стан; автоматичне повторне надсилання не виконувалося.", en: "Run creation could not be confirmed. The current active status was checked; no automatic retry was made." },
