  "reports.distanceHelp": { ru: "Расстояние между сохранёнными GPS-наблюдениями внутри подтверждённых поездок.", uk: "Відстань між збереженими GPS-спостереженнями всередині підтверджених поїздок.", en: "Distance between stored GPS observations within confirmed trips." },
  "reports.stops": { ru: "Остановки", uk: "Зупинки", en: "Stops" },
  "reports.stopHelp": { ru: "Подтверждение остановки: {duration}", uk: "Підтвердження зупинки: {duration}", en: "Stop confirmation: {duration}" },
  "reports.gapHelp": { ru: "Разрыв между соседними наблюдениями более {duration}. Время до первого и после последнего наблюдения не учитывается.", uk: "Розрив між сусідніми спостереженнями понад {duration}. Час до першого та після останнього спостереження не враховується.", en: "Adjacent observations more than {duration} apart. Time before the first and after the last observation is excluded." },
