export type MessageKey = keyof typeof MESSAGE_CATALOG;
export type MessageParameters = Readonly<Record<string, string | number>>;

function project(locale: AppLocale): Readonly<Record<MessageKey, string>> {
  return Object.freeze(Object.fromEntries(Object.entries(MESSAGE_CATALOG).map(([key, value]) => [key, value[locale]])) as Record<MessageKey, string>);
}

export const MESSAGES: Readonly<Record<AppLocale, Readonly<Record<MessageKey, string>>>> = Object.freeze({
  ru: project("ru"),
  uk: project("uk"),
  en: project("en"),
});
